import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.CWdVbaJB.js";const g=JSON.parse('{"title":"Projects","description":"","frontmatter":{"title":"Projects"},"headers":[],"relativePath":"platform/projects.md","filePath":"platform/projects.md"}'),s={name:"platform/projects.md"};function i(d,e,n,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="projects" tabindex="-1">Projects <a class="header-anchor" href="#projects" aria-label="Permalink to &quot;Projects&quot;">​</a></h1><p>Projects organize your traces, findings, and API keys into isolated groups within a workspace. Use projects to separate environments, teams, or applications.</p><h2 id="creating-a-project" tabindex="-1">Creating a Project <a class="header-anchor" href="#creating-a-project" aria-label="Permalink to &quot;Creating a Project&quot;">​</a></h2><ol><li>Navigate to the <strong>Admin</strong> tab</li><li>Click <strong>New Project</strong></li><li>Enter a project name — a URL-friendly slug is generated automatically</li></ol><p>Only workspace admins can create projects.</p><h2 id="project-features" tabindex="-1">Project Features <a class="header-anchor" href="#project-features" aria-label="Permalink to &quot;Project Features&quot;">​</a></h2><h3 id="trace-isolation" tabindex="-1">Trace Isolation <a class="header-anchor" href="#trace-isolation" aria-label="Permalink to &quot;Trace Isolation&quot;">​</a></h3><p>Each trace can be tagged to a project. Use project-scoped API keys to automatically tag traces on ingest, or set the <code>projectId</code> field in your SDK.</p><h3 id="rbac" tabindex="-1">RBAC <a class="header-anchor" href="#rbac" aria-label="Permalink to &quot;RBAC&quot;">​</a></h3><p>Project membership controls who can see project data:</p><ul><li><strong>Admins</strong> see all projects in the workspace</li><li><strong>Members</strong> see only projects they&#39;ve been added to</li><li>Workspace-level data (traces without a project) is visible to everyone</li></ul><h3 id="per-project-api-keys" tabindex="-1">Per-Project API Keys <a class="header-anchor" href="#per-project-api-keys" aria-label="Permalink to &quot;Per-Project API Keys&quot;">​</a></h3><p>Create API keys scoped to a specific project in <strong>Settings &gt; API Keys</strong>. Traces ingested with a project-scoped key are automatically tagged to that project.</p><h2 id="managing-members" tabindex="-1">Managing Members <a class="header-anchor" href="#managing-members" aria-label="Permalink to &quot;Managing Members&quot;">​</a></h2><ol><li>In the Admin tab, find the project row</li><li>Click the <strong>Members</strong> icon</li><li>Use the checkboxes to add or remove users</li><li>Changes save automatically</li></ol><p>Members can be assigned roles at the project level.</p><h2 id="project-lifecycle-archive-delete-recovery" tabindex="-1">Project lifecycle: archive, delete &amp; recovery <a class="header-anchor" href="#project-lifecycle-archive-delete-recovery" aria-label="Permalink to &quot;Project lifecycle: archive, delete &amp; recovery&quot;">​</a></h2><p>Projects move through a staged lifecycle designed so that <strong>no single action permanently destroys data</strong>. A project is only ever removed for good after two deliberate admin decisions and two separate recovery windows have elapsed.</p><p>All lifecycle actions — archive, delete, restore, and break-glass recovery — are <strong>admin-only</strong> and <strong>audited</strong>.</p><table tabindex="0"><thead><tr><th>Stage</th><th>How it gets here</th><th>Visible?</th><th>Recoverable?</th><th>Window</th></tr></thead><tbody><tr><td><strong>Active</strong></td><td>Default state</td><td>Yes</td><td>—</td><td>—</td></tr><tr><td><strong>Archived</strong></td><td>Admin archives</td><td>In the archived list</td><td><strong>Self-service restore</strong> by any admin</td><td><strong>30 days</strong></td></tr><tr><td><strong>Deleted</strong></td><td>Admin hard-deletes an <em>archived</em> project</td><td>Hidden everywhere</td><td><strong>Break-glass restore</strong> by an admin</td><td><strong>~15 days</strong></td></tr><tr><td><strong>Purged</strong></td><td>Automated job, after the grace window</td><td>—</td><td><strong>No — irreversible</strong></td><td>permanent</td></tr></tbody></table><h3 id="archiving" tabindex="-1">Archiving <a class="header-anchor" href="#archiving" aria-label="Permalink to &quot;Archiving&quot;">​</a></h3><p>Archiving a project:</p><ol><li>Hides it from the default project list</li><li>Starts a <strong>30-day</strong> restore window</li><li>Shows a warning banner to project members</li></ol><p>An archived project keeps all of its data. Nothing is deleted at archive time.</p><h3 id="restore-from-archive" tabindex="-1">Restore from archive <a class="header-anchor" href="#restore-from-archive" aria-label="Permalink to &quot;Restore from archive&quot;">​</a></h3><p>Archived projects can be restored within the 30-day window:</p><ol><li>Find the project in the archived list</li><li>Click <strong>Restore</strong></li><li>The 30-day timer is cleared and the project returns to active</li></ol><p>If an archived project is never restored, it is eventually tombstoned (see Deleting) and then purged automatically.</p><h3 id="deleting-archived-only-two-step" tabindex="-1">Deleting (archived-only, two-step) <a class="header-anchor" href="#deleting-archived-only-two-step" aria-label="Permalink to &quot;Deleting (archived-only, two-step)&quot;">​</a></h3><p>Hard-delete is <strong>only allowed on projects that are already archived</strong> — you cannot delete an active project in one step. This two-step gate (archive, then delete) is deliberate: it means a permanent removal always reflects two separate decisions.</p><p>Before a delete is confirmed, you are shown the exact <strong>blast radius</strong> — the full count of records that will be destroyed across the selected projects:</p><ul><li>Projects</li><li>Traces</li><li>Findings</li><li>Ingest events</li><li>Cost ledger records</li><li>API keys</li><li>Users who will be <strong>unlinked</strong> from the projects (their workspace access is unaffected)</li></ul><p>To proceed you must <strong>type a confirmation phrase</strong> that encodes the scope — for example <code>delete 12 projects</code> (or <code>delete 1 project</code> for a single project). The phrase is validated against the count the <strong>server</strong> resolves, so a trivial <code>yes</code>/<code>OK</code>, a stale count, or a mismatched phrase is rejected.</p><p>When you confirm, the selected projects are immediately tombstoned — they disappear from every view — and a <strong>~15-day recovery grace window</strong> begins. No data is physically deleted yet.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Delete is a bulk, instantaneous action across all views. The confirmation phrase is bound to the <strong>project count</strong>, not the individual project IDs — double-check your selection before confirming.</p></div><h3 id="break-glass-recovery-of-a-deleted-project" tabindex="-1">Break-glass recovery of a deleted project <a class="header-anchor" href="#break-glass-recovery-of-a-deleted-project" aria-label="Permalink to &quot;Break-glass recovery of a deleted project&quot;">​</a></h3><p>A hard-deleted project is tombstoned, not destroyed. For the <strong>~15-day grace window</strong> its data is still physically present and an admin can <strong>restore it</strong> (break-glass recovery). Recovered projects return to the archived state with a fresh 30-day window.</p><p>Recovery is possible for as long as the project has not yet been purged. In production the grace window has a hard floor, so a misconfiguration cannot make a delete instantly permanent.</p><h3 id="permanent-purge" tabindex="-1">Permanent purge <a class="header-anchor" href="#permanent-purge" aria-label="Permalink to &quot;Permanent purge&quot;">​</a></h3><p>Once the grace window elapses, an automated job <strong>permanently removes</strong> the project and all of its data — traces, findings, ingest events, cost ledger records, API keys, project-member links, and the project record itself. After purge there is <strong>no recovery path</strong> by any means.</p><p>A warning email is sent at day 25 of the archive window to workspace admins before a project is tombstoned by the automated timer.</p><h3 id="bulk-operations-and-limits" tabindex="-1">Bulk operations and limits <a class="header-anchor" href="#bulk-operations-and-limits" aria-label="Permalink to &quot;Bulk operations and limits&quot;">​</a></h3><p>Both archive and delete can be applied to a multi-select of projects in a single action, with per-project checkboxes and select-all in the Admin tab. Per-request caps keep bulk operations safe:</p><table tabindex="0"><thead><tr><th>Operation</th><th>Max per request</th></tr></thead><tbody><tr><td>Bulk archive</td><td><strong>500 projects</strong></td></tr><tr><td>Bulk delete</td><td><strong>50 projects</strong></td></tr></tbody></table><p>Deletes are capped lower than archives because they are rarer and higher-stakes; delete more than 50 projects as multiple deliberate batches. Requests over the cap are rejected before any work is done. Invalid entries in a batch (not archived, belonging to another workspace, or already deleted) are <strong>skipped with a reason</strong> rather than failing the whole operation.</p><h3 id="banner-dismissal" tabindex="-1">Banner Dismissal <a class="header-anchor" href="#banner-dismissal" aria-label="Permalink to &quot;Banner Dismissal&quot;">​</a></h3><p>The archive warning banner can be dismissed per user. Dismissals are archive-cycle-aware — if a project is restored and re-archived, the banner reappears.</p><h2 id="audit-trail" tabindex="-1">Audit Trail <a class="header-anchor" href="#audit-trail" aria-label="Permalink to &quot;Audit Trail&quot;">​</a></h2><p>All project actions are logged:</p><table tabindex="0"><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td><code>project.created</code></td><td>New project created</td></tr><tr><td><code>project.renamed</code></td><td>Project name changed</td></tr><tr><td><code>project.archived</code></td><td>Project archived</td></tr><tr><td><code>project.restored</code></td><td>Project restored from archive (or break-glass recovery of a deleted project)</td></tr><tr><td><code>project.hard_deleted</code></td><td>Project deleted (tombstoned), recorded with its blast-radius counts</td></tr><tr><td><code>project.purged</code></td><td>Deleted project permanently purged after the grace window</td></tr><tr><td><code>project_member.added</code></td><td>User added to project</td></tr><tr><td><code>project_member.removed</code></td><td>User removed from project</td></tr><tr><td><code>project_member.role_changed</code></td><td>Member role updated</td></tr></tbody></table>',50)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
